// int is_blueprint_loaded(string path)
//
// Report whether the program for 'path' is already resident in memory,
// without forcing it to be compiled or loaded.  find_object() consults the
// object registry only, so it is exactly the "is the blueprint loaded" test;
// with flag 1 it would behave like load_object() and trigger a compile.

public int is_blueprint_loaded(string path) {
    if (!path) return 0;
    return find_object(path) ? 1 : 0;
}
